class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }
        ListNode slow = head, fast = head.next;     // fast 先走一步，slow 停在前半段末尾
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode mid = slow.next;                   // 从中间断开
        slow.next = null;
        ListNode left = sortList(head), right = sortList(mid);
        ListNode dummy = new ListNode(), cur = dummy;
        while (left != null && right != null) {     // 合并两个有序链表
            if (left.val <= right.val) {
                cur.next = left;
                left = left.next;
            } else {
                cur.next = right;
                right = right.next;
            }
            cur = cur.next;
        }
        cur.next = left != null ? left : right;
        return dummy.next;
    }
}

